#include <bits/stdc++.h>
using namespace std;

long long f(long long n) {
    const int Len = 400000;
    vector<long long> pi_upper(Len), pi_lower(Len);
    for (int i = 1; i < Len; ++i) {
        pi_lower[i] = i;
        pi_upper[i] = n / i;
    }
    vector<bool> isPrime(Len, true);
    isPrime[0] = false;
    isPrime[1] = false;

    vector<int> primeList;
    for (int i = 2; i < Len; ++i) {
        if (!isPrime[i]) continue;
        primeList.push_back(i);
        for (int j = i * 2; j < Len; j += i) {
            isPrime[j] = false;
        }
    }

    for (size_t t = 0; t < primeList.size(); ++t) {
        int p = primeList[t];
        for (int i = 1; i < Len && n / i >= (long long)p * p; ++i) {
            long long val = (long long)p * i;
            if (val < Len) {
                pi_upper[i] -= pi_upper[val] - (t + 1);
            } else {
                pi_upper[i] -= pi_lower[(int)(n / i / p)] - (t + 1);
            }
        }
        for (int i = Len - 1; i >= (long long)p * p; --i) {
            pi_lower[i] -= pi_lower[i / p] - (t + 1);
        }
    }

    long long ans = 0;
    for (auto p : primeList) {
        if ((long long)p * p > n) break;
        if ((long long)p * p * p <= n && (long long)p * p * p > 0) ++ans;
        if (n / p > p) {
            if (p < Len)
                ans += pi_upper[p] - pi_lower[p];
            else
                ans += pi_lower[(int)(n / p)] - pi_lower[p];
        }
    }
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    cin >> n;
    cout << f(n) << "\n";
    return 0;
}

